131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
135	        if (!normalizeAndValidateFields(owner)) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
139	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
140	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
141	        }
142	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
143	        owner.setRegistrationDate(registrationDate);
144	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
145	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
146	        }
147	        owner.setHouseholdId(householdId(owner));
148	        owner.setIdentityKey(identityKey(owner));
149	        if (isDuplicate(owner)) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
153	        if (!sharesHousehold && hasExistingHousehold(owner)) {
154	            return new ResponseEntity<>(HttpStatus.CONFLICT);
155	        }
156	        if (countOwnersInCity(owner.getCity()) >= 50) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        assignRegistrationAttributes(owner, sharesHousehold);
160	        this.clinicService.saveOwner(owner);
161	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
162	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
163	        HttpHeaders headers = new HttpHeaders();
164	        headers.setLocation(UriComponentsBuilder.newInstance()
165	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
166	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
167	    }
168	
169	    /**
170	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
171	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
172	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
173	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
174	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
175	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
176	     */
177	    private boolean normalizeAndValidateFields(Owner owner) {
178	        String address = normalizeAddress(owner.getAddress());
179	        if (address.isEmpty()) {
180	            return false;
181	        }
182	        owner.setAddress(address);
183	        if (owner.getEmail() != null) {
184	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
185	            if (!EMAIL_PATTERN.matcher(email).matches()) {
186	                return false;
187	            }
188	            if (isDisposableEmailDomain(email)) {
189	                return false;
190	            }
191	            owner.setEmail(email);
192	        }
193	        if (!isPostcodeValidForCity(owner)) {
194	            return false;
195	        }
196	        String telephone = normalizeTelephone(owner.getTelephone());
197	        if (telephone == null) {
198	            return false;
199	        }
200	        owner.setTelephone(telephone);
201	        return true;
202	    }
203	
204	    /**
205	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
206	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
207	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
208	     */
209	    private static boolean isDisposableEmailDomain(String email) {
210	        int at = email.lastIndexOf('@');
211	        if (at < 0) {
212	            return false;
213	        }
214	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
215	    }
