217	    /**
218	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
219	     * computed against the owner population rather than carried on the owner itself (currently the
220	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
221	     * listing intentionally omits these flags.
222	     */
223	    private OwnerDto buildOwnerDto(Owner owner) {
224	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
225	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
226	        return ownerDto;
227	    }
