211	    /**
212	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
213	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
214	     * ({@link #householdMemberCount}), and add 3 for tenure over 365 days (whole days from
215	     * {@link #registrationDate} to today).
216	     */
217	    @Transient
218	    public Integer getMembershipPoints() {
219	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
220	            this.registrationDate);
221	    }
222	
223	    /**
224	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
225	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
226	     */
227	    @Transient
228	    public Integer getMembershipLevel() {
229	        return membershipLevel(getMembershipPoints());
230	    }
231	
232	    /** The membership points derived from the given factors: they start at 0, add 2 when
233	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
234	     *  more ({@code householdMemberCount}), and add 3 for tenure over 365 days (whole days from
235	     *  {@code registrationDate} to today). */
236	    private static int membershipPoints(String email, Integer namesakeCount,
237	            Integer householdMemberCount, LocalDate registrationDate) {
238	        int points = 0;
239	        if (email != null && !email.isBlank()) {
240	            points += 2;
241	        }
242	        if (namesakeCount != null && namesakeCount == 0) {
243	            points += 1;
244	        }
245	        if (householdMemberCount != null && householdMemberCount >= 3) {
246	            points += 2;
247	        }
248	        if (registrationDate != null
249	                && java.time.temporal.ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
250	            points += 3;
251	        }
252	        return points;
253	    }
254	
255	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
256	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
257	    private static int membershipLevel(int points) {
258	        if (points >= 6) {
259	            return 4;
260	        }
261	        if (points >= 4) {
262	            return 3;
263	        }
264	        if (points >= 2) {
265	            return 2;
266	        }
267	        return 1;
268	    }
